create extension if not exists pgcrypto;
create table if not exists sellers(id uuid primary key default gen_random_uuid(),company_name text not null,country text not null,city text,email text not null,created_at timestamptz not null default now());
create table if not exists assets(id uuid primary key default gen_random_uuid(),court_id text unique not null,manufacturer text not null,model text,year_installed int,country text not null,city text,type text,grade text check(grade in ('A','B','C','D')),asking_price_eur numeric,estimated_low_eur numeric,estimated_high_eur numeric,glass_thickness_mm numeric,turf_condition text,structure_condition text,lighting_included boolean default false,fip_status text default 'Unknown',description text,status text default 'draft',seller_id uuid references sellers(id),created_at timestamptz not null default now());
create table if not exists inquiries(id uuid primary key default gen_random_uuid(),asset_id uuid references assets(id) on delete cascade,buyer_company text,buyer_country text,buyer_email text,message text,created_at timestamptz not null default now());
create table if not exists inspections(id uuid primary key default gen_random_uuid(),asset_id uuid references assets(id) on delete cascade,inspector text,inspection_date date,glass_score int,steel_score int,turf_score int,lighting_score int,hardware_score int,notes text,final_grade text,created_at timestamptz not null default now());
create table if not exists service_quotes(id uuid primary key default gen_random_uuid(),asset_id uuid references assets(id),service_type text,origin_country text,destination_country text,quote_eur numeric,provider text,status text default 'requested',created_at timestamptz not null default now());
create index if not exists assets_country_idx on assets(country); create index if not exists assets_grade_idx on assets(grade); create index if not exists assets_status_idx on assets(status);
